use hypercurve::{Classification,CurveContext,ExactCurveError,Point2,RationalBezier2,RationalQuadraticBezier2,Real};
fn kind<T>(value:Classification<T>)->String{match value{Classification::Decided(_)=>"finite".into(),Classification::Uncertain(r)=>format!("{r:?}")}}
fn exact_kind<T>(value:Result<T,ExactCurveError>)->String{match value{Ok(_)=>"finite".into(),Err(ExactCurveError::Blocked(b))=>format!("{:?}",b.reason()),Err(_)=>"invalid".into()}}
fn main(){
 for (bits,lower) in [(128,"1070618286762869505858242456326784268487/340282366920938463463374607431768211456"),(1024,""),(4096,"")]{
  let lower:Real=lower.parse().unwrap();let weight=Real::from(2).sqrt().unwrap()+Real::from(3).sqrt().unwrap()-lower;
  // The sum of the integer square roots is a strict lower bound.
  let tower_sign=weight.quadratic_tower_sign();
  let division=match &weight / &weight{Ok(v)=>{assert_eq!(v,Real::one());"finite".into()},Err(e)=>e.to_string()};
  println!("bits={bits} zero_status={:?} tower_sign={tower_sign:?} scalar_division={division}",weight.zero_status());
  let native=RationalQuadraticBezier2::try_new(Point2::from_values(-1,0),Point2::from_values(0,1),Point2::from_values(1,0),weight.clone(),weight.clone(),weight.clone()).unwrap();
  let general=RationalBezier2::try_new(vec![Point2::from_values(-1,0),Point2::from_values(0,1),Point2::from_values(1,0)],vec![weight.clone();3]).unwrap();
  let half=(Real::one()/Real::from(2)).unwrap();
  for (pi,policy)in [CurveContext::STRICT,CurveContext::APPROXIMATE_512].iter().enumerate(){
   println!("bits={bits} policy={pi} native={} general={} derivative={} derivatives={}",kind(native.point_at(half.clone(),policy)),exact_kind(general.point_at(&half,policy)),exact_kind(general.derivative_at(&half,policy)),exact_kind(general.derivatives_at(&half,3,policy)));
  }
 }
 println!("projection_probe_complete");
}
